import json
for line in open('/workspace/out/cde_runs.jsonl'):
    r = json.loads(line)
    print(r['target_id'], r['run_at'], r['weapon_class'], r['fuze'], 'CER', r['cer_m'])
# T-05 sensitivity: POL shows 5-15 at boat landing by 0330L + 2-6 ice-truck drivers (night bin uses 4)
cer=190
def f(d, constr):
    bf = 0.60 if d<=0.25*cer else (0.30 if d<=0.5*cer else (0.10 if d<=cer else 0.0))
    mod = {'concrete':0.8,'masonry':1.0,'light':1.3,'open-air':1.5}[constr]
    return bf*mod*0.6  # delay
objs=[('C1 adjacent whse(guards)',60,'concrete',5),('C2 residential block',120,'masonry',55),('C3 fish market',140,'open-air',None),('C4 mosque',170,'masonry',1),('C5 fuel station',230,'light',1)]
for mkt in [4,9,12,19]:
    tot=0
    for name,d,c,occ in objs:
        o = mkt if 'market' in name else occ
        if d<=cer: tot += o*f(d,c)
    print(f"T-05 est with market occ {mkt:>2} at 0330L: {round(tot,1)}")
EOF"}

